  "implementation": "def solve(case):
    # Validate input structure
    if 'lengths' not in case or 'scores' not in case or 'budget' not in case:
        raise ValueError("Missing required fields: lengths, scores, budget")
    lengths = case['lengths']
    scores = case['scores']
    budget = case['budget']
    if not isinstance(lengths, list) or not isinstance(scores, list):
        raise ValueError("lengths and scores must be lists")
    if len(lengths) != len(scores):
        raise ValueError("lengths and scores must have same length")
    for l in lengths:
        if not isinstance(l, int) or l < 0:
            raise ValueError("lengths must be non-negative integers")
    for s in scores:
        if not isinstance(s, (int, float)):
            raise ValueError("scores must be numeric")
    if not isinstance(budget, int) or budget < 0:
        raise ValueError("budget must be a non-negative integer")

    n = len(lengths)
    # dp[cap] = (total_score, total_tokens, indices_tuple)  or None if unreachable
    dp = [None] * (budget + 1)
    dp[0] = (0.0, 0, ())  # empty selection

    def better(a, b):
        # Return True if a is better than b
        if a[0] != b[0]:
            return a[0] > b[0]
        if a[1] != b[1]:
            return a[1] < b[1]
        # lexicographic comparison of indices tuples (already increasing)
        return a[2] < b[2]

    for i in range(n):
        l = lengths[i]
        s = float(scores[i])
        for cap in range(budget, l - 1, -1):
            prev = dp[cap - l]
            if prev is not None:
                new_score = prev[0] + s
                new_tokens = prev[1] + l
                new_indices = prev[2] + (i,)
                candidate = (new_score, new_tokens, new_indices)
                if dp[cap] is None or better(candidate, dp[cap]):
                    dp[cap] = candidate

    # Choose best among all capacities
    best = None
    for cap in range(budget + 1):
        state = dp[cap]
        if state is not None:
            if best is None or better(state, best):
                best = state

    # best is guaranteed to exist because dp[0] always there
    total_score, tokens_used, indices = best
    return {
        'selected_indices': list(indices),
        'tokens_used': tokens_used,
        'total_score': total_score
    }
